int linear(int a[], int n, int t) {
    for (int i = 0; i < n; i++) {
        if (a[i] == t) {
            return i;
        }
    }
    return -1;
}

int binary(int a[], int n, int t) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == t) return mid;
        if (a[mid] < t) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}
